func TestG2Endomorphism(t *testing.T) {
	t.Parallel()
	parameters := gopter.DefaultTestParameters()
	if testing.Short() {
		parameters.MinSuccessfulTests = nbFuzzShort
	} else {
		parameters.MinSuccessfulTests = nbFuzz
	}

	properties := gopter.NewProperties(parameters)

	properties.Property("[BN254] check that phi(P) = lambdaGLV * P", prop.ForAll(
		func(a fptower.E2) bool {
			var p, res1, res2 G2Jac
			g := MapToG2(a)
			p.FromAffine(&g)
			res1.phi(&p)
			res2.mulWindowed(&p, &lambdaGLV)

			return p.IsInSubGroup() && res1.Equal(&res2)
		},
		GenE2(),
	))

	properties.Property("[BN254] check that phi^2(P) + phi(P) + P = 0", prop.ForAll(
		func(a fptower.E2) bool {
			var p, res, tmp G2Jac
			g := MapToG2(a)
			p.FromAffine(&g)
			tmp.phi(&p)
			res.phi(&tmp).
				AddAssign(&tmp).
				AddAssign(&p)

			return res.Z.IsZero()
		},
		GenE2(),
	))

	properties.Property("[BN254] [3]P == [2]P+P", prop.ForAll(
		func(a fptower.E2) bool {
			var p, res1, res2 G2Jac
			g := MapToG2(a)
			p.FromAffine(&g)
			res1.Triple(&p)
			res2.Double(&p).
				AddAssign(&p)

			return res1.Equal(&res2)
		},
		GenE2(),
	))

	properties.Property("[BN254] check that psi^2(P) = -phi(P)", prop.ForAll(
		func(a fptower.E2) bool {
			var p, res1, res2 G2Jac
			g := MapToG2(a)
			p.FromAffine(&g)
			res1.psi(&p).psi(&res1).Neg(&res1)
			res2.phi(&p)

			return p.IsInSubGroup() && res1.Equal(&res2)
		},
		GenE2(),
	))

	properties.TestingRun(t, gopter.ConsoleReporter(false))
}

