func fuzzCofactorOfG2(f fptower.E2) G2Jac {
	var res, jac, a, b, c G2Jac
	aff := MapToCurve2(&f)
	jac.FromAffine(&aff)
	// [x₀+1]P + ψ([x₀]P) + ψ²([x₀]P) - ψ³([2x₀]P) = [r]P
	a.mulBySeed(&jac)
	b.psi(&a)
	a.AddAssign(&jac)
	res.psi(&b)
	c.Set(&res).
		AddAssign(&b).
		AddAssign(&a)
	res.psi(&res).
		Double(&res).
		SubAssign(&c)
	return res
}

func fuzzG2Jac(p *G2Jac, f fptower.E2) G2Jac {
	var res G2Jac
	res.X.Mul(&p.X, &f).Mul(&res.X, &f)
	res.Y.Mul(&p.Y, &f).Mul(&res.Y, &f).Mul(&res.Y, &f)
	res.Z.Mul(&p.Z, &f)
	return res
}

func fuzzg2JacExtended(p *g2JacExtended, f fptower.E2) g2JacExtended {
	var res g2JacExtended
	var ff, fff fptower.E2
	ff.Square(&f)
	fff.Mul(&ff, &f)
	res.X.Mul(&p.X, &ff)
	res.Y.Mul(&p.Y, &fff)
	res.ZZ.Mul(&p.ZZ, &ff)
	res.ZZZ.Mul(&p.ZZZ, &fff)
	return res
}
